"""
Measurement only (no motion is changed): the beaker and the left hand through the carry from PICK: UP to PLACE: OVER.

    python experiments/carry_boundary_replay.py RECORDING_DIR OUT_NPZ [--t0 76.5 --t1 84.0]

Replays the recording (src/replay.py, states verified bit-identical) and records at every physics step (750 Hz) between t0 and t1 (sim seconds): the time, the beaker body's
position and rotation, the left hand tool point's position and rotation, the pad centre and the pad frame (from src/gripper_geometry.gripper_frame, as the arm module reads them).
Analysis is in experiments/carry_boundary_report.py.
"""
import argparse
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402


def main(a):
    S = {"t": [], "bp": [], "bR": [], "tp": [], "tR": [], "pp": [], "pR": []}
    ctx = {}

    def hook(step_count, data):
        if not ctx:
            m = MODEL[0]
            gf = gripper_frame(m, "left")
            ctx.update(beaker=m.body("task_beaker").id, tcp=m.body("openarm_left_hand_tcp").id, pad=np.asarray(gf["pad_center_in_tcp"], float),
                       Rp=np.column_stack([gf["closing_axis"], np.cross(gf["approach_axis"], gf["closing_axis"]), gf["approach_axis"]]))
        if not (a.t0 <= data.time <= a.t1):
            return
        R = data.xmat[ctx["tcp"]].reshape(3, 3)
        S["t"].append(data.time)
        S["bp"].append(data.xpos[ctx["beaker"]].copy())
        S["bR"].append(data.xmat[ctx["beaker"]].copy())
        S["tp"].append(data.xpos[ctx["tcp"]].copy())
        S["tR"].append(R.flatten())
        S["pp"].append(data.xpos[ctx["tcp"]] + R @ ctx["pad"])
        S["pR"].append((R @ ctx["Rp"]).flatten())

    MODEL = [None]
    orig = replay_mod.run_loop

    def spy(model, data, sources, cfg, viewer=None):
        MODEL[0] = model
        return orig(model, data, sources, cfg, viewer=viewer)

    replay_mod.run_loop = spy
    r = replay_mod.replay_run(Path(a.recording), out_dir=Path(a.out).parent / "replay_tmp", video="none", verify=True, quiet=True, step_hook=hook)
    replay_mod.run_loop = orig
    print(f"replay ok {r['ok']} ticks {r['ticks']} mismatch {r['mismatch']}", flush=True)
    tmp = Path(a.out).with_suffix(".tmp.npz")
    np.savez_compressed(tmp, **{k: np.array(v) for k, v in S.items()})
    os.replace(tmp, a.out)
    print(f"saved {len(S['t'])} steps to {a.out}", flush=True)
    return 0 if r["ok"] else 1


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("recording")
    ap.add_argument("out")
    ap.add_argument("--t0", type=float, default=76.5)
    ap.add_argument("--t1", type=float, default=84.0)
    sys.exit(main(ap.parse_args()))
